# Reuse only identical complete source values, never partial phrase substitutions.
memory={json.dumps(rows[i][1],ensure_ascii=False):th for i,th in translations.items() if rows[i][1]!=th}
for k,en in source.items():
 token=json.dumps(en,ensure_ascii=False)
 if token in memory:out[k]=memory[token]
